class Counters:
    def __init__(self):
        self.global_count = 0
        self.per_thread = {}

    def counter(self, per_user, thread_id):
        if per_user:
            self.per_thread[thread_id] = self.per_thread.get(thread_id, 0) + 1
            return self.per_thread[thread_id]
        self.global_count += 1
        return self.global_count

