coding.solution:
TOKENS = [('yyyy', '%Y'), ('SSS', '%f'), ('MM', '%m'), ('dd', '%d'), ('HH', '%H'), ('mm', '%M'), ('ss', '%S')]

def java_to_strftime(pattern):
    out, i = [], 0
    while i < len(pattern):
        if pattern[i] == "'":
            j = pattern.index("'", i + 1)
            out.append(pattern[i + 1:j])
            i = j + 1
            continue
        for tok, code in TOKENS:
            if pattern.startswith(tok, i):
                out.append(code)
                i += len(tok)
                break
        else:
            out.append(pattern[i])
            i += 1
    return ''.join(out)
